    def fmt(T, sts):
        lines = [str(T)]
        for iv in sts:
            lines.append(str(len(iv)))
            lines.extend(f'{s} {e}' for s, e in iv)
        return '\n'.join(lines)
    def rand_iv(T, m, maxlen):
        res = []
        for _ in range(m):
            s = rng.randint(0, T - 1)
            e = min(T, s + rng.randint(1, maxlen))
            res.append((s, e))
        return res
    tests = [fmt(1, [[], [], []]), fmt(1, [[(0, 1)], [], []]), fmt(5, [[(0, 5)], [(0, 5)], [(0, 5)]]),
             fmt(10, [[(1, 3), (6, 8)], [(2, 5)], [(7, 9)]]), fmt(6, [[(0, 2), (2, 4)], [(4, 6)], []]),
             fmt(8, [[], [], []]), fmt(8, [[(0, 3)], [(3, 5)], [(5, 8)]]), fmt(8, [[(1, 2)], [(1, 2)], [(1, 2)]]),
             fmt(7, [[(1, 4), (2, 3)], [(0, 1)], [(5, 6)]])]
    for T in (4, 8, 12, 20, 30):
        for _ in range(3):
            tests.append(fmt(T, [rand_iv(T, rng.randint(0, 4), max(1, T // 4)) for _ in range(3)]))
    T = 10**9
    tests.append(fmt(T, [rand_iv(T, 30000, 10**4) for _ in range(3)]))
    tests.append(fmt(T, [rand_iv(T, 30000, 2 * 10**4) for _ in range(3)]))
    tests.append(fmt(T, [rand_iv(T, 30000, 10**9) for _ in range(3)]))
    # short slots tiled so that the three students together leave many separate gaps
    sts = [[], [], []]
